function parseNumber(value) {
  if (typeof value === 'number') return value;
  const raw = String(value ?? '').trim().replace(/[R$\s]/g, '');
  if (!raw) return NaN;
  const clean = raw.includes(',') ? raw.replace(/\./g, '').replace(',', '.') : raw.replace(/\./g, '');
  return Number(clean);
}
return $input.all().map((item) => {
  const row = item.json;
  const codigo = String(row.codigo ?? row['Código'] ?? row.id ?? '').trim().toUpperCase();
  const marca = String(row.marca ?? '').trim();
  const modelo = String(row.modelo ?? '').trim();
  const cidade = String(row.cidade ?? '').trim();
  const descricao = String(row.descricao ?? '').trim();
  const fotos = Array.isArray(row.fotos) ? row.fotos : String(row.fotos ?? '').split('|').map((s) => s.trim()).filter(Boolean);
  return {json: {
    codigo, marca, modelo,
    ano: parseNumber(row.ano),
    km: parseNumber(row.km),
    preco: parseNumber(row.preco),
    cidade, fotos, descricao
  }};
});

return $input.all().map(({json: v}) => {
  const erros = [];
  if (!v.codigo) erros.push('Código ausente');
  if (!v.marca || !v.modelo) erros.push('Marca ou modelo ausente');
  if (!Number.isInteger(v.ano) || v.ano < 1980 || v.ano > new Date().getFullYear() + 1) erros.push('Ano inválido');
  if (!Number.isFinite(v.km) || v.km < 0) erros.push('Quilometragem inválida');
  if (!Number.isFinite(v.preco) || v.preco <= 0) erros.push('Preço ausente ou inválido');
  if (!v.cidade) erros.push('Cidade ausente');
  if (!Array.isArray(v.fotos) || v.fotos.length === 0) erros.push('Sem fotografias');
  if (!v.descricao) erros.push('Descrição ausente');
  return {json: {...v, estado: erros.length ? 'revisar' : 'aprovado', erros}};
});

const vistos = new Set();
return $input.all().map(({json: v}) => {
  const chave = v.codigo;
  if (chave && vistos.has(chave)) {
    return {json: {...v, estado: 'duplicado', erros: [...v.erros, 'Código de estoque repetido na importação']}};
  }
  if (chave) vistos.add(chave);
  return {json: v};
});

let sequencia = 0;
return $input.all().map(({json: v}) => {
  if (v.estado !== 'aprovado') return {json: {...v, rascunho: null, filaSimulada: null}};
  const titulo = [v.marca, v.modelo, v.ano].join(' ').trim();
  const descricao = [titulo, 'KM: ' + v.km.toLocaleString('pt-BR'), 'Cidade: ' + v.cidade,
    'Preço: R$ ' + v.preco.toLocaleString('pt-BR'), v.descricao].join('\n');
  // Apenas simulação em memória; não dispara nem reserva trabalho real.
  const posicao = ++sequencia;
  return {json: {
    ...v, rascunho: {titulo, descricao, imagens: v.fotos},
    filaSimulada: {posicao, estado: 'rascunho', agendamentoReal: false}
  }};
});

const dados = $input.all().map((x) => x.json);
const aprovados = dados.filter((v) => v.estado === 'aprovado');
const revisar = dados.filter((v) => v.estado === 'revisar');
const duplicados = dados.filter((v) => v.estado === 'duplicado');
return [{json: {
  titulo: 'Auto Flow vs n8n — ensaio isolado',
  execucao: 'MANUAL / SOMENTE SIMULACAO',
  observacao: 'Não grava no Auto Flow, não abre o Brave e não publica no Marketplace.',
  metricas: {
    recebidos: dados.length,
    aprovados: aprovados.length,
    revisar: revisar.length,
    duplicados: duplicados.length,
    rascunhosGerados: aprovados.length
  },
  filaSimulada: aprovados.map((v) => ({codigo: v.codigo, titulo: v.rascunho.titulo,
    fotos: v.rascunho.imagens.length, posicao: v.filaSimulada.posicao})),
  revisar: revisar.map((v) => ({codigo: v.codigo, motivos: v.erros})),
  duplicados: duplicados.map((v) => ({codigo: v.codigo, motivos: v.erros})),
  registros: dados
}}];
